"""
AG BRIDGE MODULE — standalone signal relay engine
===================================================
Extracted from AG TradeBridge. This ONE file carries the full
"TradingView -> MT5" signal-bridge logic, with its OWN internal
storage (no database, no dependency on any other file).

Drop this file into ANY FastAPI project and do:

    from bridge_module import bridge_router, add_strategy, add_license
    app.include_router(bridge_router)

    add_strategy("mystrategy", secret="some-secret", name="My Strategy")
    add_license("LIC-0001", days=30)

That's it — the site now accepts TradingView webhooks at
POST /master/mystrategy and MT5 EAs can poll GET /api/pull/LIC-0001.

--------------------------------------------------------------
HOW IT WORKS (3 pieces)
--------------------------------------------------------------
1. TradingView (or anything) sends a webhook:
     POST /master/{strategy_id}
     body: {"secret": "...", "action": "buy", "symbol": "XAUUSD",
            "price": 2634.5, "swing_price": 2630.1}

2. The signal is validated (build_signal) and queued for every
   active license subscribed to that strategy.

3. The MT5 EA polls:
     GET /api/pull/{license_id}?account=12345&ea=MyEA&v=1.0
   and receives the next queued signal as plain text:
     "buy,XAUUSD,2634.5,2630.1,,"
   or an empty string if nothing is pending.

--------------------------------------------------------------
MANAGEMENT FUNCTIONS (call these from your own admin code)
--------------------------------------------------------------
add_strategy(sid, secret, name)      -> register a signal source
add_license(lid, days, account=None) -> register a subscriber
subscribe(lid, sid)                  -> license follows a strategy
unsubscribe(lid, sid)
pause(lid, paused=True)              -> stop sending to this license
set_ea_file(path_or_bytes, filename) -> enable /download/ea

Everything is stored in memory (STRATEGIES / LICENSES / PENDING).
Swap the dicts for a real database later if you outgrow memory —
every read/write goes through the small helper functions below,
so that's a contained change.
"""

import time
import json
from datetime import datetime, timedelta
from fastapi import APIRouter, Request
from fastapi.responses import PlainTextResponse, Response

bridge_router = APIRouter()

# ── internal storage (swap for a DB later if needed) ──
STRATEGIES = {}   # {sid: {"secret":..., "name":..., "active":True}}
LICENSES   = {}   # {lid: {"expires": iso_str, "account": None, "paused": False, "subs": []}}
PENDING    = {}   # {lid: ["buy,XAUUSD,2634.5,2630.1,,", ...]}
LASTSEEN   = {}   # {lid: {"ts":..., "ea":..., "account":..., "ver":...}}
CFGSENT    = {}   # {lid: last_config_push_ts}

_EA_BYTES = None
_EA_FILENAME = "AG_Trade_Connector.ex5"

CONFIG_MIN_VERSION = "1.22"


# ═══════════════════════════════════════════════════════════
#  MANAGEMENT — call these from your own code / admin panel
# ═══════════════════════════════════════════════════════════
def add_strategy(sid, secret, name):
    STRATEGIES[sid] = {"secret": secret, "name": name, "active": True}

def remove_strategy(sid):
    STRATEGIES.pop(sid, None)

def add_license(lid, days=30, account=None):
    LICENSES[lid] = {
        "expires": (datetime.now() + timedelta(days=days)).isoformat(),
        "account": account,
        "paused": False,
        "subs": [],
    }

def extend_license(lid, days):
    if lid in LICENSES:
        base = datetime.fromisoformat(LICENSES[lid]["expires"])
        if base < datetime.now():
            base = datetime.now()
        LICENSES[lid]["expires"] = (base + timedelta(days=days)).isoformat()

def subscribe(lid, sid):
    if lid in LICENSES and sid not in LICENSES[lid]["subs"]:
        LICENSES[lid]["subs"].append(sid)

def unsubscribe(lid, sid):
    if lid in LICENSES and sid in LICENSES[lid]["subs"]:
        LICENSES[lid]["subs"].remove(sid)

def pause(lid, paused=True):
    if lid in LICENSES:
        LICENSES[lid]["paused"] = paused

def set_ea_file(data, filename="AG_Trade_Connector.ex5"):
    """data: bytes, or a filesystem path (str) to read bytes from."""
    global _EA_BYTES, _EA_FILENAME
    if isinstance(data, (bytes, bytearray)):
        _EA_BYTES = bytes(data)
    else:
        with open(data, "rb") as f:
            _EA_BYTES = f.read()
    _EA_FILENAME = filename


# ═══════════════════════════════════════════════════════════
#  INTERNAL HELPERS
# ═══════════════════════════════════════════════════════════
def _active(exp):
    return exp and datetime.now() < datetime.fromisoformat(exp)

def _ver_tuple(v):
    try:
        return tuple(int(x) for x in str(v).strip().split("."))
    except Exception:
        return (0,)

def build_signal(action, symbol, price, swing, use_swing):
    """Returns (signal_string, sl_mode, note). signal_string is None if rejected."""
    action = str(action).lower().strip()
    symbol = str(symbol).strip()

    if action not in ("buy", "sell"):
        return None, None, f"bad action '{action}'"
    if not symbol:
        return None, None, "no symbol"
    try:
        price = float(price)
    except (TypeError, ValueError):
        return None, None, "bad price"
    if price <= 0:
        return None, None, "price must be > 0"

    sl, sl_mode, note = "", "DEFAULT", ""
    if use_swing and swing not in ("", None):
        try:
            sw = float(swing)
        except (TypeError, ValueError):
            sw = 0.0
        if sw <= 0:
            note = "swing invalid, EA will use its own SL"
        else:
            correct_side = (sw < price) if action == "buy" else (sw > price)
            if not correct_side:
                note = f"swing {sw} is on the wrong side for {action.upper()} — dropped"
            elif abs(price - sw) < price * 0.0002:
                note = "swing too close to entry — dropped"
            else:
                sl, sl_mode = f"{sw}", "SWING"

    return f"{action},{symbol},{price},{sl},,", sl_mode, note


# ═══════════════════════════════════════════════════════════
#  ROUTES
# ═══════════════════════════════════════════════════════════
@bridge_router.post("/master/{sid}")
async def master(sid: str, request: Request):
    strat = STRATEGIES.get(sid)
    if not strat or not strat["active"]:
        return {"status": "unknown_strategy"}

    try:
        d = json.loads((await request.body()).decode("utf-8", "ignore"))
    except Exception:
        return {"status": "bad_json"}

    if d.get("secret") != strat["secret"]:
        return {"status": "unauthorized"}

    action = str(d.get("action", "")).lower()
    symbol = d.get("symbol", "")
    price = d.get("price", "")
    swing = d.get("swing_price", "")
    if not swing:
        swing = d.get("swing_low", "") if action == "buy" else d.get("swing_high", "")

    test_sig, _, test_note = build_signal(action, symbol, price, swing, True)
    if test_sig is None:
        return {"status": "rejected", "reason": test_note}

    sent = 0
    for lid, u in LICENSES.items():
        if not _active(u["expires"]) or u.get("paused"):
            continue
        if sid not in u.get("subs", []):
            continue
        sig, _, _ = build_signal(action, symbol, price, swing, True)
        if sig is None:
            continue
        PENDING.setdefault(lid, []).append(sig)
        del PENDING[lid][20:]
        sent += 1

    return {"status": "broadcast", "strategy": strat["name"], "delivered_to": sent}


@bridge_router.get("/api/pull/{lid}", response_class=PlainTextResponse)
async def pull(lid: str, account: str = "", ea: str = "", v: str = ""):
    u = LICENSES.get(lid)
    if not u:
        return "ERROR|Invalid License ID"
    if not account:
        return "ERROR|No account number sent"
    if not _active(u["expires"]):
        return "ERROR|Subscription expired. Please renew."

    LASTSEEN[lid] = {"ts": time.time(), "ea": ea or "EA", "account": account, "ver": v or "?"}

    if u["account"] is None:
        u["account"] = account
        return "OK|License activated on this account"
    if u["account"] != account:
        return f"ERROR|License is locked to account {u['account']}. Buy another license for this account."
    if u.get("paused"):
        return ""

    q = PENDING.get(lid)
    if q:
        return q.pop(0)

    if v and _ver_tuple(v) >= _ver_tuple(CONFIG_MIN_VERSION):
        if time.time() - CFGSENT.get(lid, 0) > 60:
            CFGSENT[lid] = time.time()
            return "CONFIG|manual=1"
    return ""


@bridge_router.get("/download/ea")
async def download_ea():
    if not _EA_BYTES:
        return {"error": "EA file not configured. Call set_ea_file() first."}
    return Response(
        content=_EA_BYTES,
        media_type="application/octet-stream",
        headers={"Content-Disposition": f'attachment; filename="{_EA_FILENAME}"'},
    )


@bridge_router.get("/api/bridge/status")
async def bridge_status():
    """Quick health check — how many strategies/licenses are live."""
    return {
        "strategies": len(STRATEGIES),
        "licenses": len(LICENSES),
        "active_licenses": sum(1 for u in LICENSES.values() if _active(u["expires"])),
    }



